def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        if protocol_version is not None:
            if not isinstance(protocol_version, tuple):
                raise TypeError("protocol_version must be a tuple")
            if len(protocol_version) != 2:
                raise TypeError("protocol_version must be a tuple of two integers")
            if not all(isinstance(x, int) for x in protocol_version):
                raise TypeError("protocol_version must be a tuple of two integers")

        # Assume there is a class attribute or method that provides the available handlers
        # For example, cls._available_handlers = {(3, 5): Handler35, (4, 0): Handler40, ...}
        available_handlers = getattr(cls, '_available_handlers', {})

        if protocol_version is None:
            return dict(available_handlers)
        else:
            if protocol_version in available_handlers:
                return {protocol_version: available_handlers[protocol_version]}
            else:
                return {}

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self._data.index(key)
    except ValueError:
        raise KeyError(f"Key {key} not found")

def values(self, *keys):
        """ Return the values of the record, optionally filtering to
        include only certain values by index or key.

        :param keys: indexes or keys of the items to include; if none
                     are provided, all values will be included
        :return: list of values
        :rtype: list
        """
        if not keys:
            return list(self._values)

        result = []
        for key in keys:
            if isinstance(key, int):
                if 0 <= key < len(self._values):
                    result.append(self._values[key])
                else:
                    raise IndexError("Index out of range")
            elif isinstance(key, str):
                if key in self._keys:
                    result.append(self._values[self._keys.index(key)])
                else:
                    raise KeyError("Key not found")
            else:
                raise TypeError("Keys must be integers or strings")
        return result

def data(self, *keys):
        """ Return the keys and values of this record as a dictionary,
        optionally including only certain values by index or key. Keys
        provided in the items that are not in the record will be
        inserted with a value of :const:`None`; indexes provided
        that are out of bounds will trigger an :exc:`IndexError`.

        :param keys: indexes or keys of the items to include; if none
                      are provided, all values will be included
        :return: dictionary of values, keyed by field name
        :raises: :exc:`IndexError` if an out-of-bounds index is specified
        """
        if not keys:
            return dict(self._data)

        result = {}
        for key in keys:
            if isinstance(key, int):
                if key < 0 or key >= len(self._data):
                    raise IndexError(f"Index {key} out of bounds")
                # Get the field name at this index
                field_name = self._field_names[key]
                result[field_name] = self._data[key]
            else:
                # key is a string (field name)
                if key in self._data:
                    result[key] = self._data[key]
                else:
                    result[key] = None
        return result

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    class Point:
        def __init__(self, *args, **kwargs):
            self.fields = fields
            self.srid_map = srid_map
            self.values = {}
            for i, field in enumerate(fields):
                if i < len(args):
                    self.values[field] = args[i]
                elif field in kwargs:
                    self.values[field] = kwargs[field]
                else:
                    self.values[field] = None

        def __repr__(self):
            field_strs = [f"{field}={self.values[field]!r}" for field in self.fields]
            return f"{name}({', '.join(field_strs)})"

        def __eq__(self, other):
            if not isinstance(other, Point):
                return False
            return self.values == other.values

        def __hash__(self):
            return hash(tuple(self.values[field] for field in self.fields))

    Point.__name__ = name
    return Point

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    import warnings
    import functools

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    if not isinstance(seq, Sequence):
        raise TypeError("Input must be a Sequence")
    if not all(isinstance(item, str) for item in seq):
        raise TypeError("All items in the sequence must be strings")

    # Deterministic shuffle: sort by a hash of the string
    # Using a stable, deterministic approach
    return sorted(seq, key=lambda s: hash(s))

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    parts = s.split('.')
    result = []
    for part in parts:
        if not part.isdigit():
            raise ValueError(f"Invalid version component: {part}")
        result.append(int(part))
    return tuple(result)

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorator(func):
        cache = {}
        order = []
        lock = threading.Lock()

        def wrapper(*args, **kwargs):
            # Create a key for the cache
            if typed:
                key = (args, frozenset(kwargs.items()))
            else:
                key = (args, frozenset(kwargs.items()))

            with lock:
                # Check if key is in cache and not expired
                if key in cache:
                    value, timestamp = cache[key]
                    if timer() - timestamp < ttl:
                        # Move to end of order (most recently used)
                        if key in order:
                            order.remove(key)
                        order.append(key)
                        return value
                    else:
                        # Expired, remove from cache
                        del cache[key]
                        if key in order:
                            order.remove(key)

                # Call the function
                result = func(*args, **kwargs)

                # Store in cache
                cache[key] = (result, timer())
                order.append(key)

                # Evict least recently used if over maxsize
                while len(order) > maxsize:
                    oldest_key = order.pop(0)
                    if oldest_key in cache:
                        del cache[oldest_key]

                return result

        wrapper.cache_info = lambda: {"hits": 0, "misses": 0, "size": len(cache), "maxsize": maxsize}
        wrapper.cache_clear = lambda: (cache.clear(), order.clear())
        return wrapper
    return decorator

