def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("Both arguments must be dictionaries")

    result = {}

    for key, value1 in d1.items():
        if key not in d2:
            result[key] = value1
        else:
            value2 = d2[key]
            if isinstance(value1, dict) and isinstance(value2, dict):
                if level == 0:
                    # At level 0, we don't recurse, so if both are dicts,
                    # we consider them different if they are not the same object? 
                    # Actually, the docstring says: "For level 1, if a key is present both in d1 and d2 but has different values, it is included into the difference."
                    # This implies that for level > 1, we recurse. For level == 1, we do not recurse, so we compare values directly.
                    # If level == 0, we should not recurse either.
                    # Let's re-read: "level sets the maximum depth of recursion. For infinite recursion, set that to -1. For level 1, if a key is present both in d1 and d2 but has different values, it is included into the difference."
                    # This suggests that level=1 means we only look at the top level. So if a key is in both, and the values are different (including if both are dicts but different), we include it.
                    # If level > 1, we recurse.
                    # If level == 0, we probably should not recurse either, similar to level 1.
                    # Let's assume level <= 1 means no recursion.
                    if value1 != value2:
                        result[key] = value1
                else:
                    # Recurse
                    sub_diff = difference(value1, value2, level - 1)
                    if sub_diff:
                        result[key] = sub_diff
            else:
                # Not both dicts, so compare directly
                if value1 != value2:
                    result[key] = value1

    return result

def fill(self, coord, weight=1):
        """Fill histogram at *coord* with the given *weight*.

        Coordinates outside the histogram edges are ignored.
        """
        if not isinstance(coord, (int, float)):
            raise TypeError("coord must be a number")
        if not isinstance(weight, (int, float)):
            raise TypeError("weight must be a number")
        if weight < 0:
            raise ValueError("weight must be non-negative")

        # Check if coord is within the histogram edges
        if self._edges is None:
            raise ValueError("Histogram edges not set")

        if coord < self._edges[0] or coord >= self._edges[-1]:
            return

        # Find the bin index
        import bisect
        idx = bisect.bisect_right(self._edges, coord) - 1
        if idx < 0 or idx >= len(self._counts):
            return

        self._counts[idx] += weight

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    if not hasattr(app, 'spec') or not hasattr(app.spec, 'manifest'):
        return {}

    manifest = app.spec.manifest
    if not isinstance(manifest, dict):
        return {}

    observer_schemas = {}

    for resource_name, resource in manifest.items():
        if not isinstance(resource, dict):
            continue

        # Check if a custom observer schema is already specified
        if 'observerSchema' in resource:
            continue

        # Generate default observer schema based on resource kind
        kind = resource.get('kind', '')
        api_version = resource.get('apiVersion', '')

        default_schema = {
            'kind': kind,
            'apiVersion': api_version,
            'name': resource.get('metadata', {}).get('name', resource_name),
            'namespace': resource.get('metadata', {}).get('namespace', 'default'),
            'status': {}
        }

        # Add resource-specific default fields
        if kind == 'Deployment':
            default_schema['status'] = {
                'replicas': 0,
                'readyReplicas': 0,
                'availableReplicas': 0,
                'updatedReplicas': 0
            }
        elif kind == 'StatefulSet':
            default_schema['status'] = {
                'replicas': 0,
                'readyReplicas': 0,
                'currentReplicas': 0,
                'updatedReplicas': 0
            }
        elif kind == 'DaemonSet':
            default_schema['status'] = {
                'desiredNumberScheduled': 0,
                'currentNumberScheduled': 0,
                'numberReady': 0,
                'numberAvailable': 0,
                'numberUnavailable': 0
            }
        elif kind == 'Service':
            default_schema['status'] = {
                'loadBalancer': {}
            }
        elif kind == 'Pod':
            default_schema['status'] = {
                'phase': 'Pending',
                'conditions': []
            }
        elif kind == 'Job':
            default_schema['status'] = {
                'succeeded': 0,
                'failed': 0,
                'active': 0
            }
        elif kind == 'CronJob':
            default_schema['status'] = {
                'lastScheduleTime': None,
                'lastSuccessfulTime': None
            }

        observer_schemas[resource_name] = default_schema

    return observer_schemas

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    if not hasattr(self, 'status'):
        return prefix + "Unknown"
    return prefix + str(self.status)

def status_str(self, prefix=''):
        """Return string representation of validation log, with optional prefix."""
        if not hasattr(self, 'log') or self.log is None:
            return prefix + "No validation log available."

        if isinstance(self.log, str):
            return prefix + self.log

        if isinstance(self.log, list):
            if not self.log:
                return prefix + "No validation issues found."
            lines = [prefix + line for line in self.log]
            return '\n'.join(lines)

        if isinstance(self.log, dict):
            if not self.log:
                return prefix + "No validation issues found."
            lines = []
            for key, value in self.log.items():
                if isinstance(value, list):
                    for item in value:
                        lines.append(prefix + f"{key}: {item}")
                else:
                    lines.append(prefix + f"{key}: {value}")
            return '\n'.join(lines)

        return prefix + str(self.log)

def validate(self, inventory, extract_spec_version=False):
        """Validate a given inventory.

        If extract_spec_version is True then will look at the type value to determine
        the specification version. In the case that there is no type value or it isn't
        valid, then other tests will be based on the version given in self.spec_version.
        """
        if not isinstance(inventory, dict):
            raise ValueError("Inventory must be a dictionary")

        spec_version = self.spec_version

        if extract_spec_version:
            type_value = inventory.get('type')
            if type_value is not None:
                # Try to extract spec version from type value
                # Assuming type value might be in a format like "spec_version" or contain version info
                # For now, we'll just check if it's a valid string and use it if it looks like a version
                if isinstance(type_value, str):
                    # Simple heuristic: if it contains a dot, assume it's a version
                    if '.' in type_value:
                        spec_version = type_value
                    else:
                        # If no dot, maybe it's just a type name, keep original spec_version
                        pass
                # If type_value is not a string or doesn't look like a version, keep original spec_version

        # Now perform validation based on spec_version
        # This is a placeholder for actual validation logic
        # For example, check required fields based on spec_version
        required_fields = {
            '1.0': ['name', 'version'],
            '2.0': ['name', 'version', 'type'],
        }

        if spec_version not in required_fields:
            raise ValueError(f"Unknown specification version: {spec_version}")

        for field in required_fields[spec_version]:
            if field not in inventory:
                raise ValueError(f"Missing required field: {field}")

        return True

def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""
        # Collect all digests from manifest files
        manifest_digests = set()
        for file_path in manifest_files:
            try:
                with open(file_path, 'r') as f:
                    for line in f:
                        line = line.strip()
                        if line:
                            manifest_digests.add(line)
            except Exception as e:
                raise ValueError(f"Error reading manifest file {file_path}: {e}")

        # Check that all digests used are present in the manifest
        missing_digests = digests_used - manifest_digests
        if missing_digests:
            raise ValueError(f"Digests used but not present in manifest: {missing_digests}")

        # Check that all digests in manifest are used
        unused_digests = manifest_digests - digests_used
        if unused_digests:
            raise ValueError(f"Digests present in manifest but not used: {unused_digests}")

        return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")
    if not isinstance(version, (int, str)):
        raise TypeError("version must be an integer or string")

    # Check if version exists in inventory
    if version not in inventory:
        raise ValueError(f"Version {version} not found in inventory")

    version_data = inventory[version]

    if not isinstance(version_data, dict):
        raise TypeError(f"Version data for {version} must be a dictionary")

    # Initialize the result map
    logical_path_map = {}

    # Process the version data to build the map
    # Assuming version_data has a structure that maps logical paths to content files
    # This is a generic implementation that handles common structures

    if 'files' in version_data:
        files = version_data['files']
        if isinstance(files, dict):
            for logical_path, content_files in files.items():
                if isinstance(content_files, (list, tuple, set)):
                    logical_path_map[logical_path] = set(content_files)
                elif isinstance(content_files, str):
                    logical_path_map[logical_path] = {content_files}
                else:
                    logical_path_map[logical_path] = {content_files}
        elif isinstance(files, list):
            # If files is a list, assume each item is a dict with 'logical_path' and 'content_files'
            for file_info in files:
                if isinstance(file_info, dict):
                    logical_path = file_info.get('logical_path')
                    content_files = file_info.get('content_files', [])
                    if logical_path is not None:
                        if isinstance(content_files, (list, tuple, set)):
                            logical_path_map[logical_path] = set(content_files)
                        elif isinstance(content_files, str):
                            logical_path_map[logical_path] = {content_files}
                        else:
                            logical_path_map[logical_path] = {content_files}
    elif 'logical_paths' in version_data:
        logical_paths = version_data['logical_paths']
        if isinstance(logical_paths, dict):
            for logical_path, content_files in logical_paths.items():
                if isinstance(content_files, (list, tuple, set)):
                    logical_path_map[logical_path] = set(content_files)
                elif isinstance(content_files, str):
                    logical_path_map[logical_path] = {content_files}
                else:
                    logical_path_map[logical_path] = {content_files}

    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        if not isinstance(fixity, dict):
            raise ValueError("Fixity must be a dictionary")

        if "files" not in fixity:
            raise ValueError("Fixity block must contain a 'files' key")

        files = fixity["files"]
        if not isinstance(files, list):
            raise ValueError("Fixity 'files' must be a list")

        for file_entry in files:
            if not isinstance(file_entry, dict):
                raise ValueError("Each file entry in fixity must be a dictionary")

            if "path" not in file_entry:
                raise ValueError("Each file entry in fixity must contain a 'path' key")

            file_path = file_entry["path"]
            if not isinstance(file_path, str):
                raise ValueError("File path in fixity must be a string")

            if file_path not in manifest_files:
                raise ValueError(f"File '{file_path}' in fixity is not listed in the manifest")

            if "checksum" not in file_entry:
                raise ValueError("Each file entry in fixity must contain a 'checksum' key")

            checksum = file_entry["checksum"]
            if not isinstance(checksum, str):
                raise ValueError("Checksum in fixity must be a string")

            if "algorithm" not in file_entry:
                raise ValueError("Each file entry in fixity must contain an 'algorithm' key")

            algorithm = file_entry["algorithm"]
            if not isinstance(algorithm, str):
                raise ValueError("Algorithm in fixity must be a string")

        return True

def files_list(path):
