    if node is None:
        raise ValueError("node cannot be None")
    if not isinstance(pubdate_xpaths, (list, tuple)):
        raise TypeError("pubdate_xpaths must be a list or tuple of XPath expressions")

    for xpath in pubdate_xpaths:
        if not isinstance(xpath, str):
            raise TypeError("Each XPath expression must be a string")
        try:
            result = node.xpath(xpath)
            if result:
                return result[0]
        except Exception:
            # If an XPath expression fails, continue to the next one
            continue

    return None

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    if sys.version_info[0] == 2:
        def wrapper(*args, **kwargs):
            result = namefunc(*args, **kwargs)
            if isinstance(result, unicode):
                return result.encode('utf-8')
            return result
        return wrapper
    else:
        return namefunc

