def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError("Expected a class, got {}".format(type(cls)))
    result = set()
    for sub in cls.__subclasses__():
        result.add(sub)
        result.update(subclasses(sub))
    return result

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not string:
        return 0

    # Build a mapping from character to its index in the alphabet
    char_to_index = {char: idx for idx, char in enumerate(alphabet)}

    result = 0
    base = len(alphabet)

    for char in string:
        if char not in char_to_index:
            raise ValueError(f"Character '{char}' is not in the given alphabet")
        result = result * base + char_to_index[char]

    return result

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if len(name) >= 2 and name[0] == name[-1] and name[0] in ('"', "'"):
        return name[1:-1]
    return name

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = 1 if sys.platform != 'win32' else 0
    elif platform not in (0, 1):
        raise ValueError("platform must be 'this', 0, or 1")

    if platform == 1:
        # POSIX: use shlex.split
        return shlex.split(s)
    else:
        # Windows/CMD: use a regex-based approach
        # This is a simplified version that handles common cases
        # For a more robust implementation, consider using a proper parser
        # Here we use a regex that handles quoted strings and escapes
        pattern = r'(?:"([^"\\]*(?:\\.[^"\\]*)*)"|\'([^\'\\]*(?:\\.[^\'\\]*)*)\'|\\.|[^\s\\]+)'
        result = []
        for match in re.finditer(pattern, s):
            if match.group(1) is not None:
                # Double-quoted string
                result.append(match.group(1).replace('\\"', '"').replace('\\\\', '\\'))
            elif match.group(2) is not None:
                # Single-quoted string
                result.append(match.group(2).replace("\\'", "'").replace('\\\\', '\\'))
            else:
                # Unquoted token
                token = match.group(0)
                # Handle escape sequences
                token = token.replace('\\"', '"').replace("\\'", "'").replace('\\\\', '\\')
                result.append(token)
        return result

def addignored(ignored):
    try:
        # Run git ls-files --ignored --exclude-standard to get ignored files
        result = subprocess.run(
            ['git', 'ls-files', '--ignored', '--exclude-standard'],
            capture_output=True,
            text=True,
            check=True
        )

        # Get the output and split into lines
        output = result.stdout.strip()

        if not output:
            return ""

        # Split into list of filenames
        files = output.split('\n')

        # Filter for only ignored files (those that are in the ignored list)
        # The ignored parameter is a list of filenames to filter for
        if ignored is not None:
            ignored_set = set(ignored)
            filtered_files = [f for f in files if f in ignored_set]
        else:
            filtered_files = files

        # Sort the list
        filtered_files.sort()

        # Join with commas
        return ','.join(filtered_files)

    except subprocess.CalledProcessError as e:
        raise Exception(f"Git command failed: {e.stderr}")
    except Exception as e:
        raise Exception(f"Error processing ignored files: {str(e)}")

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        # Check if the host is a known localhost name
        if host in ('localhost', '127.0.0.1', '::1'):
            return True

        # Try to resolve the hostname and check if it resolves to a loopback address
        import socket
        addr_info = socket.getaddrinfo(host, None)
        for family, socktype, proto, canonname, sockaddr in addr_info:
            ip = sockaddr[0]
            if ip in ('127.0.0.1', '::1'):
                return True
            # Check if it's a loopback address
            if family == socket.AF_INET:
                import ipaddress
                try:
                    if ipaddress.ip_address(ip).is_loopback:
                        return True
                except ValueError:
                    pass
            elif family == socket.AF_INET6:
                import ipaddress
                try:
                    if ipaddress.ip_address(ip).is_loopback:
                        return True
                except ValueError:
                    pass
        return False
    except Exception:
        return False

def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    try:
        # Check if we're on Windows
        if os.name != 'nt':
            return False

        # Check if we're in a git bash environment
        # Git bash typically sets the MSYSTEM environment variable
        # or has specific environment variables set
        if 'MSYSTEM' in os.environ:
            return True

        # Also check for the presence of git bash specific environment variables
        if 'GIT_BASH' in os.environ:
            return True

        # Check if the shell is bash
        if 'SHELL' in os.environ and 'bash' in os.environ['SHELL'].lower():
            # Additional check: git bash on Windows usually has specific paths
            if 'git' in os.environ.get('PATH', '').lower():
                return True

        return False
    except Exception:
        return False

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    '''
    # Validate inputs
    if not isinstance(config_filename, str) or not config_filename:
        raise ValueError("config_filename must be a non-empty string")
    if not isinstance(rendered_config, str):
        raise ValueError("rendered_config must be a string")
    if not isinstance(mode, int):
        raise ValueError("mode must be an integer")
    if not isinstance(overwrite, bool):
        raise ValueError("overwrite must be a boolean")

    # Check if file exists and overwrite is False
    if os.path.exists(config_filename) and not overwrite:
        raise FileExistsError(f"File {config_filename} already exists and overwrite is False")

    # Create containing directories if needed
    config_dir = os.path.dirname(config_filename)
    if config_dir:
        os.makedirs(config_dir, exist_ok=True)

    # Write the configuration
    try:
        with open(config_filename, 'w') as f:
            f.write(rendered_config)
        # Set the file permissions
        os.chmod(config_filename, mode)
    except Exception as e:
        raise IOError(f"Failed to write configuration file: {e}")

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    if not isinstance(matcher, str):
        raise TypeError("matcher must be a string")

    # Check if the matcher contains a default value
    if '=' in matcher:
        name, default = matcher.split('=', 1)
    else:
        name = matcher
        default = None

    # Get the value from environment
    value = os.environ.get(name)

    if value is not None:
        return value
    elif default is not None:
        return default
    else:
        raise ValueError(f"Environment variable '{name}' is not defined and no default value provided")

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    if isinstance(commands, str):
        commands = [commands]
    if not isinstance(commands, (list, tuple)):
        raise TypeError("commands must be a string or a list/tuple of strings")
    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple")

    full_command = commands + list(args)

    if verbose:
        print("Running command: " + " ".join(full_command))

    try:
        if hide_stderr:
            result = subprocess.run(
                full_command,
                cwd=cwd,
                env=env,
                stdout=subprocess.PIPE,
                stderr=subprocess.DEVNULL,
                check=True
            )
        else:
            result = subprocess.run(
                full_command,
                cwd=cwd,
                env=env,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                check=True
            )
        return result
    except subprocess.CalledProcessError as e:
        if verbose:
            print("Command failed with return code:", e.returncode)
            if e.stdout:
                print("stdout:", e.stdout.decode())
            if e.stderr:
                print("stderr:", e.stderr.decode())
        raise
    except Exception as e:
        if verbose:
            print("Error running command:", str(e))
        raise

