def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    try:
        # Validate shape
        if not isinstance(shape, tuple):
            raise TypeError("shape must be a tuple")
        if any(not isinstance(dim, int) or dim < 0 for dim in shape):
            raise ValueError("shape dimensions must be non-negative integers")

        # Validate dtype
        if not isinstance(dtype, np.dtype):
            dtype = np.dtype(dtype)

        # Create the array
        return np.zeros(shape, dtype=dtype)
    except Exception as e:
        raise e

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging

    import os

    import json

    import yaml

    import re
    if not config_filenames:
        return {}, []

    if not isinstance(config_filenames, (list, tuple)):
        config_filenames = [config_filenames]

    if overrides is None:
        overrides = {}

    if not isinstance(overrides, dict):
        raise ValueError("overrides must be a dictionary")

    parsed_configs = {}
    error_records = []

    env_pattern = re.compile(r'\$\{([^}]+)\}')

    def resolve_env_vars(obj):
        if isinstance(obj, str):
            def replace_env(match):
                var_name = match.group(1)
                return os.environ.get(var_name, match.group(0))
            return env_pattern.sub(replace_env, obj)
        elif isinstance(obj, dict):
            return {k: resolve_env_vars(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [resolve_env_vars(item) for item in obj]
        else:
            return obj

    def apply_overrides(config, overrides_dict):
        if not overrides_dict:
            return config
        result = config.copy() if isinstance(config, dict) else config
        if isinstance(result, dict):
            for key, value in overrides_dict.items():
                if key in result and isinstance(result[key], dict) and isinstance(value, dict):
                    result[key] = apply_overrides(result[key], value)
                else:
                    result[key] = value
        return result

    for filename in config_filenames:
        try:
            if not isinstance(filename, str):
                raise ValueError(f"Configuration filename must be a string, got {type(filename)}")

            if not os.path.exists(filename):
                raise FileNotFoundError(f"Configuration file not found: {filename}")

            with open(filename, 'r', encoding='utf-8') as f:
                content = f.read()

            # Determine file type by extension
            ext = os.path.splitext(filename)[1].lower()

            if ext in ['.json', '.json5']:
                try:
                    config = json.loads(content)
                except json.JSONDecodeError as e:
                    raise ValueError(f"Invalid JSON in {filename}: {e}")
            elif ext in ['.yaml', '.yml']:
                try:
                    config = yaml.safe_load(content)
                except yaml.YAMLError as e:
                    raise ValueError(f"Invalid YAML in {filename}: {e}")
            else:
                # Try JSON first, then YAML
                try:
                    config = json.loads(content)
                except json.JSONDecodeError:
                    try:
                        config = yaml.safe_load(content)
                    except yaml.YAMLError as e:
                        raise ValueError(f"Unable to parse {filename} as JSON or YAML: {e}")

            if config is None:
                config = {}

            if not isinstance(config, dict):
                raise ValueError(f"Configuration in {filename} must be a dictionary, got {type(config)}")

            # Apply overrides
            config = apply_overrides(config, overrides)

            # Resolve environment variables if requested
            if resolve_env:
                config = resolve_env_vars(config)

            parsed_configs[filename] = config

        except Exception as e:
            # Create a LogRecord for the error
            logger = logging.getLogger(__name__)
            record = logger.makeRecord(
                name=logger.name,
                level=logging.ERROR,
                fn=__file__,
                lno=0,
                msg=f"Error loading configuration file {filename}: {str(e)}",
                args=(),
                exc_info=(type(e), e, e.__traceback__)
            )
            error_records.append(record)

    return parsed_configs, error_records

def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        if protocol_version is not None:
            if not isinstance(protocol_version, tuple):
                raise TypeError("protocol_version must be a tuple")
            # Check if the specific version is supported
            if protocol_version in cls._protocol_handlers:
                return {protocol_version: cls._protocol_handlers[protocol_version]}
            else:
                return {}
        else:
            # Return all available protocol handlers
            return dict(cls._protocol_handlers)

def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        """
        if not isinstance(values, (list, tuple, set, frozenset)):
            raise TypeError("values must be an iterable of strings")

        # Convert each raw value to a Bookmark object
        bookmarks = []
        for value in values:
            if not isinstance(value, str):
                raise TypeError("Each value must be a string")
            # Assuming there's a way to create a Bookmark from a raw string
            # This is a placeholder; adjust based on actual Bookmark class implementation
            try:
