def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
        # Check if it's a public message
        if hasattr(request, 'public_message') and request.public_message:
            return 'public_message'

        # Check if it's a private message
        if hasattr(request, 'private_message') and request.private_message:
            return 'private_message'

        # Check if it's a legacy payload
        if hasattr(request, 'legacy_payload') and request.legacy_payload:
            return 'legacy_payload'

        # If none of the above, return None or raise an exception
        return None

    except Exception as e:
        raise ValueError(f"Failed to identify request: {str(e)}")

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        # Check if the request has a path that starts with /_matrix
        if hasattr(request, 'path') and request.path.startswith('/_matrix'):
            return True
        # Check if the request has a URL that contains /_matrix
        if hasattr(request, 'url') and '/_matrix' in request.url:
            return True
        # Check if the request has a host that looks like a Matrix server
        if hasattr(request, 'host') and request.host:
            # This is a heuristic, not a definitive check
            pass
        return False
    except Exception:
        return False

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    """
    if dt is None:
        raise ValueError("dt cannot be None")
    if not hasattr(dt, 'strftime'):
        raise TypeError("dt must be a datetime object with strftime method")
    return dt.strftime("%Y-%m-%d %H:%M:%S")

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        return False
    if not tag:
        return False
    # A valid tag should contain only alphanumeric characters and underscores
    # and should not start with a digit
    if not tag[0].isalpha() and tag[0] != '_':
        return False
    for char in tag:
        if not (char.isalnum() or char == '_'):
            return False
    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    result = {}
    for child in node:
        tag = child.tag
        if tag in result:
            if not isinstance(result[tag], list):
                result[tag] = [result[tag]]
            result[tag].append(child)
        else:
            result[tag] = child
    return result

def check_sender_and_entity_handle_match(sender_handle, entity_handle):
    """Ensure that sender and entity handles match.

    Basically we've already verified the sender is who they say when receiving the payload. However, the sender might
    be trying to set another author in the payload itself, since Diaspora has the sender in both the payload headers
    AND the object. We must ensure they're the same.
    """
    if sender_handle is None or entity_handle is None:
        raise ValueError("Both sender_handle and entity_handle must be provided")
    if sender_handle != entity_handle:
        raise ValueError("Sender handle and entity handle do not match")

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    if not url:
        raise ValueError("url is required")

    # Ensure the url ends with a slash if it doesn't
    if not url.endswith('/'):
        url = url + '/'

    # Default document path
    if document_path is None:
        document_path = '.well-known/nodeinfo'

    # Construct the full document URL
    document_url = url + document_path

    # Return the NodeInfo document structure
    return {
        "links": {
            "self": document_url,
            "http://nodeinfo.diaspora.software/ns/schema/2.0": document_url + "?version=2.0",
            "http://nodeinfo.diaspora.software/ns/schema/1.0": document_url + "?version=1.0"
        },
        "version": "2.0"
    }

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json

    from typing import Dict
    if not document or not isinstance(document, str):
        raise ValueError("Document must be a non-empty string")

    # Try JSON format first
    try:
        data = json.loads(document)
        if isinstance(data, dict):
            # Check if it looks like a webfinger JSON response
            if 'links' in data:
                return data
            # Maybe it's a different structure, but still valid JSON
            return data
    except json.JSONDecodeError:
        pass

    # Try XRD format (XML)
    try:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(document)

        # XRD format: <XRD xmlns="http://docs.oasis-open.org/webfinger/xrd">
        # We need to handle namespaces
        ns = {'xrd': 'http://docs.oasis-open.org/webfinger/xrd'}

        result = {}

        # Get subject
        subject_elem = root.find('xrd:subject', ns)
        if subject_elem is not None:
            result['subject'] = subject_elem.text

        # Get aliases
        aliases = []
        for alias_elem in root.findall('xrd:alias', ns):
            if alias_elem.text:
                aliases.append(alias_elem.text)
        if aliases:
            result['aliases'] = aliases

        # Get links
        links = []
        for link_elem in root.findall('xrd:link', ns):
            link = {}
            for attr in link_elem.attrib:
                # Remove namespace from attribute name if present
                if ':' in attr:
                    attr_name = attr.split(':')[-1]
                else:
                    attr_name = attr
                link[attr_name] = link_elem.attrib[attr]
            links.append(link)
        if links:
            result['links'] = links

        return result

    except ET.ParseError:
        pass

    raise ValueError("Document is not in valid JSON or XRD format")

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    import urllib.request
    import urllib.parse
    import json

    if not handle or not isinstance(handle, str):
        return None

    # Normalize the handle
    handle = handle.strip()
    if not handle:
        return None

    # If the handle is already a full URL, use it as is
    if handle.startswith("http://") or handle.startswith("https://"):
        url = handle
    else:
        # Assume it's a domain or user@domain format
        if "@" in handle:
            user, domain = handle.split("@", 1)
            # RFC 7033: .well-known/webfinger?resource=acct:user@domain
            resource = f"acct:{user}@{domain}"
            url = f"https://{domain}/.well-known/webfinger?resource={urllib.parse.quote(resource)}"
        else:
            # Just a domain, try to get the webfinger document for the domain itself
            # This is less common, but we can try
            url = f"https://{handle}/.well-known/webfinger"

    try:
        req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
        with urllib.request.urlopen(req, timeout=10) as response:
            if response.status == 200:
                content_type = response.headers.get("Content-Type", "")
                if "application/json" in content_type or "application/jrd+json" in content_type:
                    data = response.read().decode("utf-8")
                    # Validate that it's valid JSON
                    json.loads(data)
                    return data
                else:
                    return None
            else:
                return None
    except Exception:
        return None

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    import requests
    try:
        if method.lower() == "post":
            response = requests.post(url, data=data, timeout=timeout, *args, **kwargs)
        elif method.lower() == "get":
            response = requests.get(url, data=data, timeout=timeout, *args, **kwargs)
        elif method.lower() == "put":
            response = requests.put(url, data=data, timeout=timeout, *args, **kwargs)
        elif method.lower() == "delete":
            response = requests.delete(url, data=data, timeout=timeout, *args, **kwargs)
        elif method.lower() == "patch":
            response = requests.patch(url, data=data, timeout=timeout, *args, **kwargs)
        else:
            raise ValueError(f"Unsupported method: {method}")
        return response.status_code, None
    except Exception as e:
        return None, e

