def get_nested_custom_and_control_args(self, args):
        """Split input arguments to control nested and custom.

        Controls arguments: control the IR behavior. These arguments
            will not be put into the spec yml file
        Nested arguments: are used by the Ansible playbooks and will be put
            into the spec yml file.
        Custom arguments: Custom ansible variables to be used instead of the
            normal nested usage.

        :param args: the collected list of args.
        :return: (dict, dict): flat dicts (control_args, nested_args)
        """
        if not isinstance(args, list):
            raise TypeError("args must be a list")

        control_args = {}
        nested_args = {}

        for arg in args:
            if not isinstance(arg, str):
                raise TypeError("Each argument must be a string")

            if '=' in arg:
                key, value = arg.split('=', 1)
                key = key.strip()
                value = value.strip()

                # Check if it's a control argument (starts with 'control_')
                if key.startswith('control_'):
                    control_args[key] = value
                else:
                    nested_args[key] = value
            else:
                # If no '=', treat as a flag or just add to nested
                key = arg.strip()
                if key.startswith('control_'):
                    control_args[key] = True
                else:
                    nested_args[key] = True

        return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        if extra_vars is None:
            return vars_dict

        if not isinstance(vars_dict, dict):
            raise TypeError("vars_dict must be a dictionary")

        if not isinstance(extra_vars, list):
            raise TypeError("extra_vars must be a list")

        for item in extra_vars:
            if not isinstance(item, str):
                raise TypeError("Each item in extra_vars must be a string")

            if '=' not in item:
                raise ValueError(f"Invalid extra-var format: {item}. Expected 'key=value'")

            key, value = item.split('=', 1)
            key = key.strip()
            value = value.strip()

            if not key:
                raise ValueError(f"Empty key in extra-var: {item}")

            vars_dict[key] = value

        return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
       """
        if not isinstance(values_dict, dict):
            raise TypeError("values_dict must be a dictionary")

        # Define a mapping of argument names to their expected types
        # This is a simplified example; in a real scenario, this would be
        # more comprehensive and possibly data-driven
        type_mapping = {
            'port': int,
            'timeout': int,
            'retries': int,
            'verbose': bool,
            'debug': bool,
            'dry_run': bool,
            'max_connections': int,
            'buffer_size': int,
            'rate_limit': float,
            'threshold': float,
        }

        # Convert values based on the type mapping
        for key, value in values_dict.items():
            if key in type_mapping:
                target_type = type_mapping[key]
                try:
                    if target_type is bool:
                        # Handle boolean conversion
                        if isinstance(value, str):
                            value_lower = value.lower()
                            if value_lower in ('true', '1', 'yes', 'on'):
                                values_dict[key] = True
                            elif value_lower in ('false', '0', 'no', 'off'):
                                values_dict[key] = False
                            else:
                                raise ValueError(f"Cannot convert '{value}' to bool")
                        else:
                            values_dict[key] = bool(value)
                    else:
                        values_dict[key] = target_type(value)
                except (ValueError, TypeError) as e:
                    raise ValueError(f"Failed to convert argument '{key}' to {target_type.__name__}: {e}")

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    import yaml

    # Define the path to the plugin spec file
    spec_file = os.path.join(plugin_dir, 'plugin_spec.json')
    spec_file_yaml = os.path.join(plugin_dir, 'plugin_spec.yaml')

    # Check if the spec file exists
    if os.path.exists(spec_file):
        with open(spec_file, 'r') as f:
            spec = json.load(f)
    elif os.path.exists(spec_file_yaml):
        with open(spec_file_yaml, 'r') as f:
            spec = yaml.safe_load(f)
    else:
        raise FileNotFoundError(f"Plugin spec file not found in {plugin_dir}")

    # Flatten the dictionary
    def flatten_dict(d, parent_key='', sep='.'):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten_dict(v, new_key, sep=sep).items())
            else:
                items.append((new_key, v))
        return dict(items)

    return flatten_dict(spec)

def inject_config(self):
        """Set the environment variable for config path, if it is undefined."""
        import os
        if 'CONFIG_PATH' not in os.environ:
            os.environ['CONFIG_PATH'] = 'default_config.json'

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both path and root must be strings")

    if not path.startswith(root):
        raise ValueError("Path does not start with the given root")

    stripped = path[len(root):]
    # Remove leading slash if present
    if stripped.startswith('/'):
        stripped = stripped[1:]
    return stripped
